// ===== SW-018 build the embedding request =====
// R-09: the query vector MUST match the stored dimension or the <=> operator errors.
const inp = $('When Called by WF-002').first().json;
const profile = inp.requirementProfile || {};
const q = profile.normalizedQuery || inp.requirement || '';
if (!q.trim()) throw new Error('SW-018: empty query - nothing to embed.');
return [{ json: Object.assign({}, inp, { embedInput: q }) }];

const inp = $('When Called by WF-002').first().json;
const res = $json || {};
const vec = res.data && res.data[0] && res.data[0].embedding;
if (!Array.isArray(vec)) throw new Error('SW-018: embedding provider returned no vector.');
const dim = Number(inp.config.embeddingDimension) || 1536;
if (vec.length !== dim) {
  throw new Error('SW-018 R-09 dimension mismatch: stored vectors are ' + dim +
    '-dimensional but the query embedding is ' + vec.length + '. Refusing to search.');
}

// §458 keyword query text. Built HERE, not inside the SQL, so the Postgres nodes read
// it by node reference: a Postgres node REPLACES the item, so the second query cannot
// rely on $json still holding config (that produced `LIMIT undefined`).
const profile = inp.requirementProfile || {};
const expandedTerms = new Set(inp.expandedTerms || []);

// One sanitisation, three projections. Every term is split on non-alphanumerics so
// 'colour-coded' contributes two lexemes, lower-cased, de-duplicated, and
// single-character fragments dropped. The result can only contain [a-z0-9], spaces
// and pipes, so it can neither terminate the dollar quote nor smuggle a tsquery
// operator - the sanitisation is the injection barrier, not an escape.
const sanitize = list => [...new Set((list || [])
  .flatMap(k => String(k).toLowerCase().split(/[^a-z0-9]+/))
  .filter(t => t.length > 1))];

const allTerms = sanitize(profile.keywords);
// §455 states synonym/acronym expansion exists to IMPROVE RECALL. Expanded terms
// therefore widen the candidate query but must never widen the coverage
// denominator, or expansion would raise the bar a unit has to clear and make
// recall worse the more synonyms are configured.
const coreTerms = sanitize((profile.keywords || []).filter(k => !expandedTerms.has(k)));

// to_tsquery input, OR semantics. plainto_tsquery ANDs every term, which is why a
// 7-term requirement matched nothing at all; the dictionary also stems each term,
// so 'thresholds' and 'threshold' collapse to one lexeme.
// The sentinel keeps the SQL total: to_tsquery('') is a syntax ERROR, and this node
// still runs on a SemanticOnly requirement, where there are no terms by design.
const NO_TERMS = 'criinokeywordsentinel';
const keywordTsQuery = allTerms.length ? allTerms.join(' | ') : NO_TERMS;
const keywordQuery = allTerms.length ? allTerms.join(' ') : NO_TERMS;
const keywordCoreQuery = coreTerms.length ? coreTerms.join(' ') : keywordQuery;

// Both values are interpolated into SQL, so both are validated here rather than
// trusted. An absent or malformed value FAILS instead of falling back to a private
// default: a silently different gate would look like a retrieval-quality problem.
const kw = (inp.config && inp.config.keyword) || {};
const TS_CONFIGS = ['simple', 'english', 'arabic'];
const textSearchConfig = String(kw.textSearchConfig || '');
if (!TS_CONFIGS.includes(textSearchConfig)) {
  throw new Error('SW-018 §458: keyword.textSearchConfig must be one of ' +
    TS_CONFIGS.join('/') + ', got ' + JSON.stringify(kw.textSearchConfig) +
    '. Refusing to build a text-search query against an unverified configuration.');
}
const minimumWeightedCoverage = Number(kw.minimumWeightedCoverage);
if (!Number.isFinite(minimumWeightedCoverage) || minimumWeightedCoverage < 0 || minimumWeightedCoverage > 1) {
  throw new Error('SW-018 §458: keyword.minimumWeightedCoverage must be a number in [0,1], got ' +
    JSON.stringify(kw.minimumWeightedCoverage) + '. Refusing to run the keyword arm ungated.');
}
const minimumMatchedTerms = Number(kw.minimumMatchedTerms);
if (!Number.isInteger(minimumMatchedTerms) || minimumMatchedTerms < 1) {
  throw new Error('SW-018 §458: keyword.minimumMatchedTerms must be an integer >= 1, got ' +
    JSON.stringify(kw.minimumMatchedTerms) + '. Refusing to run the keyword arm ungated.');
}

return [{ json: Object.assign({}, inp, {
  queryEmbedding: vec,
  keywordQuery, keywordCoreQuery, keywordTsQuery,
  keywordTermCount: allTerms.length, keywordCoreTermCount: coreTerms.length,
  textSearchConfig, minimumWeightedCoverage, minimumMatchedTerms,
}) }];

// =============================================================================
// WF-002 Enterprise Retrieval — shared pure logic.
//
// Faithful JS port of the canonical Python reference in
// crie-canonical-v1.0.2/workflows/shared/retrieval_*.py. Formulas, weights and
// thresholds are NOT re-derived here: they come from configuration/retrieval.yaml
// (R-08) and the spec sections cited per function. Nothing in this file performs
// I/O, so every part is unit-testable outside n8n.
// =============================================================================

// --- §305 canonical defaults, used ONLY when the runtime cache has no row -----
// These are transcribed from configuration/retrieval.yaml, which is the authored
// source of truth. They are not an alternative configuration: when they are used
// the caller records configSource='canonical-default' so the substitution is
// visible in telemetry rather than silent.
const CANONICAL_RETRIEVAL_CONFIG = {
  topK: 50,
  minimumSimilarity: 0.30,
  metadataFiltering: true,
  authorityWeight: 0.25,
  rerankerEnabled: false,
  crossEncoderModel: '',
  maximumContextTokens: 8000,
  defaultStrategy: 'Hybrid',
  distanceMetric: 'Cosine',
  embeddingDimension: 1536,
  // §458 keyword retrieval. trigramSearch is OFF: whole-content similarity() is
  // length-biased (a long unit scores high on any query) and a 0.1 floor admitted
  // hundreds of unrelated units, so it was the de-facto keyword arm while FTS
  // matched nothing. Keyword retrieval is now FTS with OR semantics, gated by
  // term coverage. ranking:'BM25' is the authored §458 value; stock PostgreSQL has
  // no BM25, so ts_rank_cd is the ranking actually applied (pre-existing gap).
  keyword: {
    fullTextSearch: true, trigramSearch: false, ranking: 'BM25',
    textSearchConfig: 'english', minimumMatchedTerms: 2, minimumWeightedCoverage: 0.10,
  },
  compositeWeights: {
    semanticSimilarity: 0.35, authority: 0.25, keywordScore: 0.20,
    metadataMatch: 0.10, documentFreshness: 0.10,
  },
  freshnessEnabled: true,
  freshnessHalfLifeDays: 365,
  expansion: { metadataExpansion: true, synonymExpansion: true, acronymNormalization: true },
  deduplication: { semanticSimilarityThreshold: 0.95 },
  emptyRetrieval: { maxRetries: 3, ladder: ['retry', 'relaxMetadataFilters', 'expandSynonyms'], onExhaustion: 'InsufficientEvidence' },
  contextQuality: {
    weights: {
      coverage: 0.30, authority: 0.20, citationCompleteness: 0.20,
      knowledgeDiversity: 0.15, conflictPenalty: 0.10, freshness: 0.05,
    },
  },
};

const STOPWORDS = new Set(['the','a','an','and','or','of','to','for','in','on','with',
  'is','are','be','must','shall','should','that','this','it','as','by','at','from','will']);
const WORD_RE = /[a-z0-9][a-z0-9-]*/g;
const PUNCT_RE = /[^\w\s-]/g;
const ACRONYM_RE = /\b[A-Z][A-Z0-9]{1,}\b/g;
const ENTITY_RE = /\b[A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)*\b/g;

// --- §453 language detection -------------------------------------------------
// Arabic block U+0600..U+06FF. The pipeline is bilingual: PR-001 v1.2 keeps each
// knowledge unit in its source language, so a requirement may legitimately be
// Arabic and must not be forced to English.
function detectLanguage(text) {
  return /[؀-ۿ]/.test(String(text || '')) ? 'ar' : 'en';
}

function detectIntent(raw) {
  const low = String(raw || '').toLowerCase();
  if (['support', 'compliant', 'does it', 'can it'].some(k => low.includes(k))) return 'compliance_check';
  if (['how', 'configure', 'setup', 'steps'].some(k => low.includes(k))) return 'how_to';
  return null;
}

// --- SW-031 (canonically SW-016) Requirement Analyzer, §256/§453-455 ---------
function analyzeRequirement(rawRequirement, cfg, dictionaries, metadataHints) {
  const raw = String(rawRequirement || '');
  const hints = metadataHints || {};
  const language = detectLanguage(raw);
  const intent = detectIntent(raw);

  // Raw-case extraction BEFORE lowercasing, so entities/acronyms survive.
  const rawAcronyms = raw.match(ACRONYM_RE) || [];
  const entities = [...new Set(raw.match(ENTITY_RE) || [])].sort();

  // §453 normalise: lowercase -> strip punctuation -> tokenise -> drop stopwords
  const depunct = raw.toLowerCase().replace(PUNCT_RE, ' ');
  const tokens = (depunct.match(WORD_RE) || []).filter(t => !STOPWORDS.has(t));

  const expanded = [];
  const exp = cfg.expansion || {};

  // §453 acronym normalisation
  if (exp.acronymNormalization !== false) {
    for (const ac of rawAcronyms) {
      for (const e of (dictionaries.acronyms[ac] || [])) {
        for (const w of (String(e).toLowerCase().match(WORD_RE) || [])) {
          if (!STOPWORDS.has(w)) expanded.push(w);
        }
      }
    }
  }
  // §455 synonym expansion
  if (exp.synonymExpansion !== false) {
    for (const t of tokens.slice()) {
      for (const syn of (dictionaries.synonyms[t] || [])) {
        for (const w of (String(syn).toLowerCase().match(WORD_RE) || [])) {
          if (!STOPWORDS.has(w)) expanded.push(w);
        }
      }
    }
  }

  // §454 metadata expansion -> derived filters
  const filters = Object.assign({}, hints);
  if (exp.metadataExpansion !== false) {
    const derived = [];
    for (const t of tokens.concat(entities.map(e => e.toLowerCase()))) {
      for (const d of (dictionaries.metadata[t] || [])) derived.push(d);
    }
    if (derived.length && filters.expandedTopics === undefined) {
      filters.expandedTopics = [...new Set(derived)].sort();
    }
  }

  const keywords = [...new Set(tokens.concat(expanded))];
  const modules = Array.isArray(hints.modules) ? hints.modules : [];

  // §453 builds the normalised query from WORD_RE, which is ASCII-only. For an
  // Arabic requirement - a first-class CRIE language, not an edge case - that
  // yields NO tokens, so normalizedQuery would be the empty string and the
  // semantic arm would embed nothing. PUNCT_RE cannot be reused here either: JS
  // \w is [A-Za-z0-9_], so it strips Arabic letters as if they were punctuation.
  // The keyword arm still gets no tokens (keywords are NOT fabricated); only the
  // text handed to the multilingual embedding is repaired, and the substitution
  // is REPORTED via normalizationMode rather than happening silently.
  let normalizedQuery = tokens.join(' ');
  let normalizationMode = 'latinTokens';
  if (!normalizedQuery) {
    const scriptAgnostic = raw.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, ' ')
      .replace(/\s+/g, ' ').trim();
    if (scriptAgnostic) {
      normalizedQuery = scriptAgnostic;
      normalizationMode = 'nonLatinPassthrough';
    } else {
      normalizationMode = 'empty';
    }
  }

  return {
    normalizedQuery,
    normalizationMode,
    keywords,
    entities,
    modules,
    product: hints.product !== undefined ? hints.product : null,
    intent,
    language,
    filters,
    expandedTerms: [...new Set(expanded)],
  };
}

// --- §456 strategy selection -------------------------------------------------
function selectStrategy(profile, cfg) {
  const def = cfg.defaultStrategy || 'Hybrid';
  // Canonical §456, as implemented in retrieval_analyze.py select_strategy():
  //   no keywords              -> SemanticOnly
  //   filters but no query text -> MetadataOnly
  //   otherwise                 -> the configured default
  // The first rule is what makes non-Latin retrieval DELIBERATE. With no ASCII
  // tokens there is nothing for the keyword arm to match, so an Arabic
  // requirement runs purely on the multilingual embedding instead of drifting
  // into whole-content trigram on the raw requirement text, which is how Arabic
  // appeared to work before. Ported faithfully, including the second rule, which
  // is unreachable while normalizedQuery is derived from the same tokens.
  if (!profile.keywords.length) return 'SemanticOnly';
  if (Object.keys(profile.filters || {}).length && !profile.normalizedQuery) return 'MetadataOnly';
  return def;
}

// --- §460/§461 candidate merge ----------------------------------------------
// Scores stay INDEPENDENT (§461): merging takes the max of each dimension rather
// than summing, so a candidate found by both routes is not double-counted.
function mergeCandidates(keywordHits, semanticHits) {
  const merged = new Map();
  for (const c of keywordHits.concat(semanticHits)) {
    const k = c.evidenceId;
    const cur = merged.get(k);
    if (!cur) { merged.set(k, Object.assign({}, c)); continue; }
    cur.keywordScore = Math.max(cur.keywordScore || 0, c.keywordScore || 0);
    cur.semanticScore = Math.max(cur.semanticScore || 0, c.semanticScore || 0);
    cur.metadataScore = Math.max(cur.metadataScore || 0, c.metadataScore || 0);
  }
  return [...merged.values()];
}

// --- §439/§464 authority + §463 freshness -----------------------------------
function applyAuthorityAndFreshness(candidates, cfg, authoritySources, nowMs) {
  const vals = Object.values(authoritySources || {});
  const maxAuth = vals.length ? Math.max(...vals) : 0;
  const denom = maxAuth || 1;
  const hl = Math.max(Number(cfg.freshnessHalfLifeDays) || 365, 1);
  const now = nowMs === undefined ? Date.now() : nowMs;
  for (const c of candidates) {
    c.authorityScore = (authoritySources[c.sourceType] || 0) / denom;
    if (cfg.freshnessEnabled !== false) {
      const t = Date.parse(c.updatedAt);
      const ageDays = Number.isFinite(t) ? Math.max((now - t) / 86400000, 0) : 0;
      c.freshnessScore = Math.pow(0.5, ageDays / hl);   // exponential decay
    } else {
      c.freshnessScore = 0;
    }
  }
}

// --- §462 composite ranking --------------------------------------------------
function compositeRank(candidates, cfg) {
  const w = cfg.compositeWeights;
  const sum = Object.values(w).reduce((a, b) => a + b, 0);
  // §462: weights SHALL be configurable, and are validated to sum to 1.00.
  if (Math.abs(sum - 1) > 1e-6) {
    throw new Error('WF-002 §462: compositeWeights must sum to 1.00, got ' + sum.toFixed(4) +
      '. Refusing to rank with an invalid weighting.');
  }
  for (const c of candidates) {
    c.compositeScore =
      w.semanticSimilarity * (c.semanticScore || 0) +
      w.authority * (c.authorityScore || 0) +
      w.keywordScore * (c.keywordScore || 0) +
      w.metadataMatch * (c.metadataScore || 0) +
      w.documentFreshness * (c.freshnessScore || 0);
  }
}

// --- §466 duplicate detection ------------------------------------------------
function deduplicate(candidates) {
  const ranked = candidates.slice().sort((a, b) => b.compositeScore - a.compositeScore);
  const kept = [], seenKu = new Set(), seenEv = new Set(), seenCite = new Set(), seenText = new Set();
  for (const c of ranked) {
    const norm = String(c.text || '').toLowerCase().split(/\s+/).join(' ');
    if (seenEv.has(c.evidenceId)) continue;
    if (c.knowledgeUnitId && seenKu.has(c.knowledgeUnitId)) continue;
    if (c.citationId && seenCite.has(c.citationId)) continue;
    if (norm && seenText.has(norm)) continue;
    seenEv.add(c.evidenceId);
    if (c.knowledgeUnitId) seenKu.add(c.knowledgeUnitId);
    if (c.citationId) seenCite.add(c.citationId);
    if (norm) seenText.add(norm);
    kept.push(c);
  }
  return kept;
}

// --- SW-020 §467 conflict detection -----------------------------------------
// Conflicts SHALL be preserved, never hidden. Resolution is the Reasoning
// Engine's job, so every conflict carries resolution:'deferToReasoning'.
function detectConflicts(candidates) {
  const byClaim = new Map();
  for (const c of candidates) {
    if (c.claimKey && c.claimPolarity) {
      if (!byClaim.has(c.claimKey)) byClaim.set(c.claimKey, []);
      byClaim.get(c.claimKey).push(c);
    }
  }
  const conflicts = [];
  for (const [claimKey, group] of byClaim) {
    const polarities = new Set(group.map(c => c.claimPolarity));
    if (polarities.has(1) && polarities.has(-1)) {
      const pick = p => group.filter(c => c.claimPolarity === p).map(c => ({
        evidenceId: c.evidenceId, knowledgeUnitId: c.knowledgeUnitId, authorityScore: c.authorityScore,
      }));
      conflicts.push({ claimKey, supporting: pick(1), contradicting: pick(-1), resolution: 'deferToReasoning' });
    }
  }
  return conflicts;
}

// --- §468 deterministic compression -----------------------------------------
// NEVER AI-summarise: compression only removes duplicates and repeated citations.
function estimateTokens(text) { return Math.max(1, Math.floor((String(text || '').length + 3) / 4)); }

function compress(candidates) {
  const seenText = new Set(), seenCite = new Set(), out = [];
  for (const c0 of candidates) {
    const c = Object.assign({}, c0);
    const norm = String(c.text || '').toLowerCase().split(/\s+/).join(' ');
    if (seenText.has(norm)) continue;
    if (c.citationId && seenCite.has(c.citationId)) c.citationId = null;
    seenText.add(norm);
    if (c.citationId) seenCite.add(c.citationId);
    c.tokenEstimate = estimateTokens(c.text);
    out.push(c);
  }
  return out;
}

// --- §469 token budget: lowest-ranked removed first --------------------------
function rankOrder(candidates) {
  return candidates.slice().sort((a, b) =>
    ((b.rerankScore != null ? b.rerankScore : b.compositeScore) -
     (a.rerankScore != null ? a.rerankScore : a.compositeScore)));
}

function enforceTokenBudget(candidates, cfg) {
  const ordered = rankOrder(candidates);
  const kept = []; let total = 0;
  for (const c of ordered) {
    const t = c.tokenEstimate || estimateTokens(c.text);
    if (total + t > cfg.maximumContextTokens) continue;
    kept.push(c); total += t;
  }
  return { kept, tokenCount: total };
}

// --- §470 context quality score ---------------------------------------------
function qualityScore(candidates, conflicts, cfg) {
  if (!candidates.length) return 0;
  const w = cfg.contextQuality.weights;
  const n = candidates.length;
  const coverage = Math.min(n / Math.max(cfg.topK, 1), 1);
  const authority = candidates.reduce((a, c) => a + (c.authorityScore || 0), 0) / n;
  const citationCompleteness = candidates.filter(c => c.citationId).length / n;
  const diversity = new Set(candidates.map(c => c.knowledgeUnitId)).size / n;
  const freshness = candidates.reduce((a, c) => a + (c.freshnessScore || 0), 0) / n;
  const conflictPenalty = 1 / (1 + conflicts.length);
  const score = w.coverage * coverage + w.authority * authority +
    w.citationCompleteness * citationCompleteness + w.knowledgeDiversity * diversity +
    w.conflictPenalty * conflictPenalty + w.freshness * freshness;
  return Math.round(Math.min(Math.max(score, 0), 1) * 10000) / 10000;
}

// ===== SW-018 Hybrid Retriever - merge (§460/§461) =====
const inp = $('When Called by WF-002').first().json;
const cfg = inp.config;
const strategy = inp.strategy || cfg.defaultStrategy;

const norm = (rows, kind) => rows.filter(r => r && r.evidenceId).map(r => ({
  knowledgeUnitId: r.knowledgeUnitId, evidenceId: r.evidenceId,
  citationId: r.citationId || null, text: r.text || '',
  sourceType: r.sourceType, updatedAt: r.updatedAt,
  metadata: { category: r.category, module: r.module, feature: r.feature,
              document: r.document, page: r.page, section: r.section },
  keywordScore: Number(r.keywordScore) || 0,
  semanticScore: Number(r.semanticScore) || 0,
  metadataScore: 0,
  claimKey: null, claimPolarity: 0,
  retrievedBy: kind,
}));

// §456: only the routes the selected strategy calls for contribute candidates.
const semRows = (strategy === 'SemanticOnly' || strategy === 'Hybrid')
  ? $('Semantic Search').all().map(i => i.json) : [];
const kwRows = (strategy === 'KeywordOnly' || strategy === 'Hybrid' || strategy === 'MetadataOnly')
  ? $('Keyword Search').all().map(i => i.json) : [];

const merged = mergeCandidates(norm(kwRows, 'keyword'), norm(semRows, 'semantic'));

// §457 metadata match contributes its own INDEPENDENT score (§461) - it filters
// nothing away here, it only scores; removal is the ranking stage's job.
const f = inp.filters || {};
const topics = (f.expandedTopics || []).map(t => String(t).toLowerCase());
for (const c of merged) {
  let hits = 0, checks = 0;
  if (f.modules && f.modules.length) { checks++; if (f.modules.includes(c.metadata.module)) hits++; }
  if (topics.length) {
    checks++;
    const hay = ((c.metadata.category || '') + ' ' + (c.metadata.feature || '') + ' ' + c.text).toLowerCase();
    if (topics.some(t => hay.includes(t))) hits++;
  }
  c.metadataScore = checks ? hits / checks : 0;
}

return [{ json: Object.assign({}, inp, {
  candidates: merged,
  retrievalStats: {
    strategy,
    semanticRows: semRows.length,
    keywordRows: kwRows.length,
    candidateCount: merged.length,
  },
}) }];
